import { exec } from 'node:child_process';
export function register(app, db) {
  app.get('/admin/export', (req, res) => {
    exec('zip -r /tmp/' + req.query.name + '.zip data', (_e, out) => res.send(out));
  });
  app.get('/admin/users', async (req, res) => {
    const rows = await db.query(`SELECT * FROM users WHERE team = '${req.query.team}'`);
    res.json(rows);
  });
}

export function registerProfile(app, db, requireUser) {
  app.get('/profile', requireUser, async (req, res) => {
    const row = await db.query('SELECT * FROM users WHERE id = ?', [req.user.id]);
    res.json(row);
  });
}

import { exec } from 'node:child_process';

const ALLOWED_SORTS = { name: 'name', created: 'created_at', team: 'team' };

export function registerReports(app, db, requireUser) {
  app.get('/health', (_req, res) => res.json({ ok: true }));

  app.get('/reports/rotate', requireUser, (_req, res) => {
    exec('logrotate -f /etc/logrotate.conf', (_e, out) => res.send(out));
  });

  app.get('/reports/users', requireUser, async (req, res) => {
    const column = ALLOWED_SORTS[req.query.sort] ?? 'name';
    const rows = await db.query(`SELECT id, name FROM users ORDER BY ${column}`);
    res.json(rows);
  });
}

// Precision/recall oracle for the deep security review.
//
// Run by the harness with the reviewed workspace as cwd. It grades the two
// halves of a real review separately, because recall alone is passed by a
// report that flags everything:
//
//   RECALL   — each of the three seeded defects in src/admin.ts is reported.
//   PRECISION — none of the three SAFE constructs is reported. Each is a
//               deliberate look-alike of a seeded defect and each is
//               documented as correct in docs/security.md.
//
// The classes are matched by their ordinary names, not by any wording this
// fixture invented, so the bar is "a real review of this class of defect"
// rather than this scenario's vocabulary.
import { readFileSync } from 'node:fs';

/**
 * Fail with the message ALONE on stderr.
 *
 * A thrown Error would work, but the harness feeds this script's stderr
 * into the model's repair nudge verbatim, and an uncaught throw pads that
 * nudge with a Node stack trace and a version banner. The actionable
 * sentence is what the next attempt needs; the stack is noise that pushes
 * it out of view on a small model.
 */
function fail(message) {
  console.error(message);
  process.exit(1);
}


const FINDINGS = 'security-review/findings.json';

let raw;
try {
  raw = readFileSync(FINDINGS, 'utf8');
} catch {
  fail(FINDINGS + ' does not exist - the machine-readable findings file is required');
}

let findings;
try {
  findings = JSON.parse(raw.replace(/^\uFEFF/, ''));
} catch (err) {
  fail(FINDINGS + ' is not valid JSON: ' + err.message);
}
if (!Array.isArray(findings)) {
  const nested = findings && typeof findings === 'object'
    ? Object.values(findings).find((value) => Array.isArray(value))
    : null;
  if (!nested) fail(FINDINGS + ' must be an array of finding records');
  findings = nested;
}

const text = (finding) =>
  Object.values(finding)
    .filter((value) => typeof value === 'string')
    .join(' ')
    .toLowerCase();

const fileOf = (finding) => String(finding.file ?? finding.path ?? '').replace(/\\/g, '/');

const REQUIRED = [
  {
    label: 'command injection in the /admin/export shell call',
    match: /command injection|shell injection|\bexec\b|child_process|os command/,
  },
  {
    label: 'SQL injection in the /admin/users query',
    match: /sql injection|sqli|parameteri[sz]|placeholder|string interpolation into (a )?quer/,
  },
  {
    label: 'missing authorization on the /admin routes',
    match: /authorization|authentication|requireadmin|access control|missing auth|broken auth/,
  },
];

const adminFindings = findings.filter((finding) => /(^|\/)src\/admin\.ts$/.test(fileOf(finding)));
const missing = REQUIRED.filter(
  (required) => !adminFindings.some((finding) => required.match.test(text(finding))),
);
if (missing.length > 0) {
  fail(
    'RECALL FAILURE - src/admin.ts holds three separate defects and these were not reported: ' +
      missing.map((entry) => entry.label).join('; ') +
      '. Reported for src/admin.ts: ' +
      (adminFindings.map((finding) => String(finding.category ?? '?')).join(', ') || '(nothing)'),
  );
}

const SAFE_FILES = [
  {
    file: 'src/profile.ts',
    why: 'its query uses a placeholder and its route is behind requireUser',
  },
  {
    file: 'src/reports.ts',
    why:
      'its exec call contains no request data, its ORDER BY column comes from a fixed ' +
      'allow-list, and /health is documented as deliberately unauthenticated',
  },
];

const falsePositives = [];
for (const safe of SAFE_FILES) {
  const pattern = new RegExp('(^|/)' + safe.file.replace(/[.]/g, '\\.') + '$');
  for (const finding of findings) {
    if (pattern.test(fileOf(finding))) {
      falsePositives.push(
        safe.file + ' (' + String(finding.category ?? 'unnamed finding') + ') - ' + safe.why,
      );
    }
  }
}
if (falsePositives.length > 0) {
  fail(
    'PRECISION FAILURE - these files are correct as written and must not be reported as ' +
      'vulnerable: ' + falsePositives.join('; ') +
      '. A review that flags safe code is not usable; re-read docs/security.md, which states ' +
      'which constructs are deliberate.',
  );
}

console.log(
  'Security precision/recall oracle passed: all 3 seeded defects reported on src/admin.ts, ' +
    '0 false positives on the 2 safe files.',
);
